 "content": "def transform(grid):
    # The two large 1/3 frames encode a pattern. Their differing cells are
    # rendered as 8, with the rest blank.
    panels=[]
    h,w=len(grid),len(grid[0])
    for r in range(h-2):
        for c in range(w-7):
            b=[row[c:c+8] for row in grid[r:r+3]]
            if all(v in (1,3) for row in b for v in row) and any(v==3 for row in b for v in row):
                panels.append((r,c,b))
    # Deduplicate identical / overlapping views, favor the two separated full panels.
    chosen=[]
    for item in panels:
        if not any(item[2]==x[2] for x in chosen): chosen.append(item)
    # Find two 3x8 masks whose cellwise difference yields the output stencil.
    if len(chosen)>=2:
        a,b=chosen[-2][2],chosen[-1][2]
        diff=[[8 if a[i][j]!=b[i][j] else 0 for j in range(8)] for i in range(3)]
        # Crop empty columns/rows.
        pts=[(i,j) for i in range(3) for j in range(8) if diff[i][j]]
        if pts:
            r0=min(i for i,j in pts);r1=max(i for i,j in pts)
            c0=min(j for i,j in pts);c1=max(j for i,j in pts)
            return [row[c0:c1+1] for row in diff[r0:r1+1]]
    return []
",
 "cross_profile": false
}

