 for x in range(W):
  if g[r][x] and (r,x) not in seen:
   st=[(r,x)];seen.add((r,x)); pts=[]
   while st:
    y,z=st.pop();pts.append((y,z))
    for yy,zz in ((y-1,z),(y+1,z),(y,z-1),(y,z+1)):
     if 0<=yy<H and 0<=zz<W and g[yy][zz] and (yy,zz) not in seen:seen.add((yy,zz));st.append((yy,zz))
   r0=min(y for y,z in pts);r1=max(y for y,z in pts);c0=min(z for y,z in pts);c1=max(z for y,z in pts)
   comps.append((len(pts),(r0,c0,r1,c1)))
