def grid_after(text, marker, h, w):
    i=text.index(marker)+len(marker)
    lines=text[i:].splitlines()
    out=[]
    for line in lines:
        vals=[int(x) for x in line.split() if x.isdigit()]
        if len(vals)==w:
            out.append(vals)
            if len(out)==h: return out
    raise ValueError((marker,len(out)))
def components(g):
    h,w=len(g),len(g[0]); seen=set(); out=[]
    for r in range(h):
      for x in range(w):
        if g[r][x] and (r,x) not in seen:
          stack=[(r,x)]; seen.add((r,x)); cells=[]
          while stack:
            a,b=stack.pop(); cells.append((a,b))
            for q in ((a-1,b),(a+1,b),(a,b-1),(a,b+1)):
              if 0<=q[0]<h and 0<=q[1]<w and g[q[0]][q[1]] and q not in seen:
                seen.add(q); stack.append(q)
          rs=[p[0] for p in cells]; cs=[p[1] for p in cells]
          out.append((len(cells),(min(rs),min(cs),max(rs),max(cs)),cells))
    return sorted(out,reverse=True,key=lambda q:q[0])
def mismatch_output(g):
    comps=components(g)
    (n1,b1,a),(n2,b2,b)=comps[:2]
    print('components:',[(n,box) for n,box,_ in comps])
    r1,c1,r1b,c1b=b1; r2,c2,r2b,c2b=b2
    # align by component bounding-box top-left. Compute mismatch over max dimensions, padding with empty cells.
    hh=max(r1b-r1,r2b-r2)+1; ww=max(c1b-c1,c2b-c2)+1
    ma={(r-r1,c-c1) for r,c in a}; mb={(r-r2,c-c2) for r,c in b}
    diff={(r,x) for r in range(hh) for x in range(ww) if ((r,x) in ma)!=((r,x) in mb)}
    if not diff: return []
    ra=[q[0] for q in diff]; ca=[q[1] for q in diff]; top,bot=min(ra),max(ra); left,right=min(ca),max(ca)
