import sqlite3, re, json
DB='/home/USER/continual-arc-baselines/.workbench/stage1/HPL0-hermes-luna6-high-rnd0/frozen/held-out/play/users/u014/system/state/hermes/state.db'
c=sqlite3.connect(DB)
sid='65277219-5da9-4ae8-a4ca-44454ac23155'
msgs=dict(c.execute('select id,content from messages where session_id=? and role="user"',(sid,)))
def parse_grid(text, label):
    m=re.search(re.escape(label)+r' \((\d+)x(\d+)\):\n((?:[0-9 ]+\n?)+)', text)
    if not m: raise ValueError('missing '+label)
    h,w=map(int,m.group(1,2)); rows=[[int(x) for x in line.split()] for line in m.group(3).strip().splitlines()]
    assert len(rows)==h and all(len(r)==w for r in rows),(len(rows),[len(r) for r in rows],h,w)
    return rows
def comps(g):
    h,w=len(g),len(g[0]); seen=set(); out=[]
    for r in range(h):
      for x in range(w):
       if g[r][x] and (r,x) not in seen:
        stack=[(r,x)]; seen.add((r,x)); cells=[]
        while stack:
         y,z=stack.pop(); cells.append((y,z))
         for dy in (-1,0,1):
          for dx in (-1,0,1):
           q=(y+dy,z+dx)
           if 0<=q[0]<h and 0<=q[1]<w and g[q[0]][q[1]] and q not in seen:
            seen.add(q); stack.append(q)
        out.append(cells)
    return out
def box(g,c):
    r0=min(r for r,x in c); r1=max(r for r,x in c); c0=min(x for r,x in c); c1=max(x for r,x in c)
    return (r0,c0,[[bool(g[r][x]) for x in range(c0,c1+1)] for r in range(r0,r1+1)])
def trans(g):
    cs=comps(g)
    if len(cs)!=2: raise ValueError(f'expected 2 components, got {len(cs)}')
    a,b=[box(g,x) for x in cs]
    if len(a[2])!=len(b[2]) or len(a[2][0])!=len(b[2][0]): raise ValueError('bbox sizes differ')
    dif=[[(a[2][r][x]!=b[2][r][x]) for x in range(len(a[2][0]))] for r in range(len(a[2]))]
    ys=[r for r,row in enumerate(dif) for x,v in enumerate(row) if v]; xs=[x for row in dif for x,v in enumerate(row) if v]
    if not ys:return [[0]]
    return [[8 if dif[r][x] else 0 for x in range(min(xs),max(xs)+1)] for r in range(min(ys),max(ys)+1)]
for mid in (5,21,161):
 text=msgs[mid]; g=parse_grid(text,'input'); out=parse_grid(text,'output')
 print('DEMO',mid,'bboxes',[(b[0],b[1],len(b[2]),len(b[2][0])) for b in (box(g,x) for x in comps(g))])
 print('pred=',trans(g),'actual=',out,'match=',trans(g)==out)
t=parse_grid(msgs[201],'Test input')
print('TEST bboxes',[(b[0],b[1],len(b[2]),len(b[2][0])) for b in (box(t,x) for x in comps(t))])
print('TEST OUTPUT',json.dumps(trans(t)))
